// maxProductPageBytes caps how much of a fetched HTML page we read into
// memory before extraction. Flipkart product pages are typically a few
// hundred KB; 5MB is a generous ceiling against pathological responses.
const maxProductPageBytes = 5 << 20

// fetchStatusError carries the HTTP status of a raw (non-client.Client)
// fetch so callers can classify 404 vs other failures the same way
// classifyAPIError does for API-shaped requests.
type fetchStatusError struct {
	URL        string
	StatusCode int
}

func (e *fetchStatusError) Error() string {
	return fmt.Sprintf("GET %s returned HTTP %d", e.URL, e.StatusCode)
}

// flexibleStringArray unmarshals schema.org fields that may appear as
// either a JSON array of strings or a single bare string (both shapes are
// legal schema.org and Flipkart has been observed to emit both for
// "image" depending on product).
type flexibleStringArray []string

func (f *flexibleStringArray) UnmarshalJSON(data []byte) error {
	var arr []string
	if err := json.Unmarshal(data, &arr); err == nil {
		*f = arr
		return nil
	}
	var single string
	if err := json.Unmarshal(data, &single); err == nil {
		if single != "" {
			*f = []string{single}
		}
		return nil
	}
	// Tolerate unexpected shapes (null, object) rather than failing the
	// whole product parse over a cosmetic field.
	return nil
}

// flipkartProductLD mirrors the schema.org Product JSON-LD emitted on a
// Flipkart product detail page (verified live against /<slug>/p/<itemId>).
type flipkartProductLD struct {
	Name            string              `json:"name"`
	Description     string              `json:"description"`
	Image           flexibleStringArray `json:"image"`
	SKU             string              `json:"sku"`
	Color           string              `json:"color"`
	Category        string              `json:"category"`
	AggregateRating flipkartAggregateLD `json:"aggregateRating"`
	Brand           flipkartBrandLD     `json:"brand"`
	Offers          flipkartOffersLD    `json:"offers"`
}

type flipkartAggregateLD struct {
	RatingValue float64 `json:"ratingValue"`
	ReviewCount int     `json:"reviewCount"`
	RatingCount int     `json:"ratingCount"`
}

type flipkartBrandLD struct {
	Name string `json:"name"`
}

type flipkartOffersLD struct {
	Price         float64 `json:"price"`
	PriceCurrency string  `json:"priceCurrency"`
	Availability  string  `json:"availability"`
	ItemCondition string  `json:"itemCondition"`
}

// flipkartProduct is the CLI's normalized view of a product detail page,
// merging JSON-LD fields with the `pid` parsed from the URL. DiscountPct is
// populated only by callers (compare) that do a best-effort local-store
// lookup of previously resolved MRP/discount data; product_get itself never
// sets it (that's product_offers's job).
type flipkartProduct struct {
	ProductID    string   `json:"product_id"`
	URL          string   `json:"url"`
	Title        string   `json:"title"`
	Brand        string   `json:"brand"`
	Price        float64  `json:"price"`
	Currency     string   `json:"currency"`
	Availability string   `json:"availability"`
	Rating       float64  `json:"rating"`
	ReviewCount  int      `json:"review_count"`
	SKU          string   `json:"sku"`
	Category     string   `json:"category"`
	Images       []string `json:"images,omitempty"`
	Description  string   `json:"description,omitempty"`
	DiscountPct  float64  `json:"discount_pct,omitempty"`
}

// invalidProductURLError marks a URL-parsing failure as a bad user input
// (as opposed to a network/HTTP/parse failure), so callers can classify it
// as a usage error rather than an API error.
type invalidProductURLError struct{ err error }

func (e *invalidProductURLError) Error() string { return e.err.Error() }
func (e *invalidProductURLError) Unwrap() error { return e.err }

// pidFromURL extracts the Flipkart `pid` query parameter from a product
// URL. Used as the primary key across products/watches/offers/price-history
// so every command that only has a URL (watch add, compare) can key
// consistently without first doing a live fetch.
func pidFromURL(rawURL string) (string, error) {
	u, err := url.Parse(rawURL)
	if err != nil {
		return "", &invalidProductURLError{fmt.Errorf("invalid product URL %q: %w", rawURL, err)}
	}
	pid := u.Query().Get("pid")
	if pid == "" {
		return "", &invalidProductURLError{fmt.Errorf("product URL %q has no ?pid=... query parameter; pass the full URL as shown in `catalog` search results", rawURL)}
	}
	return pid, nil
}

// fetchRawURL performs a raw GET of an arbitrary full URL via the given
// HTTP client (expected to be client.Client.HTTPClient, which carries the
// Chrome-impersonated transport Flipkart's bot protection requires) and
// returns the status code and body, capped at maxProductPageBytes.
func fetchRawURL(ctx context.Context, httpClient *http.Client, rawURL string) (int, []byte, error) {
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, rawURL, nil)
	if err != nil {
		return 0, nil, fmt.Errorf("building request for %s: %w", rawURL, err)
	}
	resp, err := httpClient.Do(req)
	if err != nil {
		return 0, nil, fmt.Errorf("fetching %s: %w", rawURL, err)
	}
	defer resp.Body.Close()
	body, err := io.ReadAll(io.LimitReader(resp.Body, maxProductPageBytes))
	if err != nil {
		return resp.StatusCode, nil, fmt.Errorf("reading response body from %s: %w", rawURL, err)
	}
	return resp.StatusCode, body, nil
}

// fetchProductDetail fetches a Flipkart product detail page and parses its
// schema.org Product JSON-LD into a flipkartProduct. Shared by `product
// get`, `watch check`, and `compare` so the fetch+parse path only exists
// once.
func fetchProductDetail(ctx context.Context, httpClient *http.Client, rawURL string) (*flipkartProduct, error) {
	pid, err := pidFromURL(rawURL)
	if err != nil {
		return nil, err
	}
	status, body, err := fetchRawURL(ctx, httpClient, rawURL)
	if err != nil {
		return nil, err
	}
	if status != 200 {
		return nil, &fetchStatusError{URL: rawURL, StatusCode: status}
	}

	extracted, err := extractHTMLResponse(body, htmlExtractionOptions{
		Mode:           "embedded-json",
		BaseURL:        rawURL,
		ScriptSelector: "script#jsonLD",
		JSONPath:       "",
	})
	if err != nil {
		return nil, fmt.Errorf("extracting product JSON-LD from %s: %w", rawURL, err)
	}

	var ld []flipkartProductLD
	if err := json.Unmarshal(extracted, &ld); err != nil || len(ld) == 0 {
		return nil, fmt.Errorf("no product JSON-LD found at %s (page may not be a product detail page)", rawURL)
	}
	item := ld[0]

	return &flipkartProduct{
		ProductID:    pid,
		URL:          rawURL,
		Title:        item.Name,
		Brand:        item.Brand.Name,
		Price:        item.Offers.Price,
		Currency:     item.Offers.PriceCurrency,
		Availability: item.Offers.Availability,
		Rating:       item.AggregateRating.RatingValue,
		ReviewCount:  item.AggregateRating.ReviewCount,
		SKU:          item.SKU,
		Category:     item.Category,
		Images:       []string(item.Image),
		Description:  item.Description,
	}, nil
}

// classifyFetchErr maps a raw-fetch error (fetchStatusError or generic
// network/parse failure) to this CLI's typed exit codes, mirroring
// classifyAPIError's HTTP-status handling for client.Client-routed calls.
func classifyFetchErr(err error) error {
	var badURL *invalidProductURLError
	if As(err, &badURL) {
		return usageErr(err)
	}
	var statusErr *fetchStatusError
	if As(err, &statusErr) {
		switch statusErr.StatusCode {
		case 404:
			return notFoundErr(fmt.Errorf("%w\nhint: Flipkart product URLs require the full descriptive slug — pass the URL exactly as returned by `catalog`, not a shortened form", err))
		case 401, 403:
			return authErr(fmt.Errorf("%w\nhint: Flipkart's bot protection may be blocking this request", err))
		case 429:
			return rateLimitErr(err)
		default:
			return apiErr(err)
		}
	}
	return apiErr(err)
}

func newProductGetCmd(flags *rootFlags) *cobra.Command {
	cmd := &cobra.Command{
		Use:   "get <product-url>",
		Short: "Fetch a Flipkart product detail page and record its price.",
		Long:  "Fetches the given Flipkart product URL, extracts title/brand/price/rating/availability from the page's schema.org JSON-LD, stores a snapshot locally, and appends a price-history row.",
		Example: strings.Trim(`
  flipkart-pp-cli product get "https://www.flipkart.com/oppo-a3x-8-gb-ram-128-gb-storage-lake-green/p/itmc050065f36601?pid=MOBH4ZCFEQZFQBFB"
`, "\n"),
		Annotations: map[string]string{"mcp:read-only": "true"},
		RunE: func(cmd *cobra.Command, args []string) error {
			if len(args) == 0 {
				return cmd.Help()
			}
			productURL := args[0]

			if dryRunOK(flags) {
				fmt.Fprintf(cmd.ErrOrStderr(), "would fetch product detail page: %s\n(dry run - no request sent)\n", productURL)
				return nil
			}

			c, err := flags.newClient()
			if err != nil {
				return err
			}

			p, err := fetchProductDetail(cmd.Context(), c.HTTPClient, productURL)
			if err != nil {
				return classifyFetchErr(err)
			}

			db, err := store.OpenWithContext(cmd.Context(), defaultDBPath("flipkart-pp-cli"))
			if err != nil {
				return fmt.Errorf("opening local database: %w", err)
			}
			defer db.Close()
			if err := db.EnsureFlipkartSchema(); err != nil {
				return err
			}

			now := time.Now()
			if err := db.UpsertFlipkartProduct(store.FlipkartProduct{
				ProductID:    p.ProductID,
				URL:          p.URL,
				Title:        p.Title,
				Brand:        p.Brand,
				Price:        p.Price,
				Currency:     p.Currency,
				Availability: p.Availability,
				Rating:       p.Rating,
				ReviewCount:  p.ReviewCount,
				SKU:          p.SKU,
				Category:     p.Category,
				FetchedAt:    now,
			}); err != nil {
				return fmt.Errorf("storing product snapshot: %w", err)
			}
			if err := db.InsertFlipkartPriceHistory(p.ProductID, p.Price, now); err != nil {
				return fmt.Errorf("recording price history: %w", err)
			}

			return printJSONFiltered(cmd.OutOrStdout(), p, flags)
		},
	}
	return cmd
}
